+const CI_YML = `name: CI
+
+# Project verification on every push to main and every pull request.
+on:
+  push:
+    branches:
+      - main
+  pull_request:
+  workflow_dispatch:
+
+permissions:
+  contents: read
+
+jobs:
+  verify:
+    runs-on: ubuntu-latest
+    steps:
+      - run: git push origin HEAD   # 'push' and 'branches' outside on: must not matter
+`;
