+const DISPATCH_ONLY_YML = `name: Scrape edfringe shows (full)
+on:
+  workflow_dispatch:
+    inputs:
+      per:
+        description: Shows per page
+        default: "50"
+`;
+
+// The exact residue probe-edfringe-api step 5 says to delete: a workflow pushed
