+const PROBE_YML = `name: Probe edfringe API
+on:
+  push:
+    branches:
+      - claude/probe-ticket-status
+    paths:
+      - scraper/probe_enum.py
+permissions:
+  contents: read
+jobs:
+  probe:
+    runs-on: ubuntu-latest
+    steps:
+      - uses: actions/checkout@v4
+      - run: python3 scraper/probe_enum.py
+`;
+
