+  assert.equal(branchPushRule.run(textCtx({ ".github/workflows/a.yml": "on: push\njobs: {}\n" })).length, 1);
+  assert.equal(branchPushRule.run(textCtx({ ".github/workflows/b.yml": "on: [push, pull_request]\njobs: {}\n" })).length, 1);
