+
+test("a tags-only push trigger is a release workflow, not a live wire", () => {
+  assert.deepEqual(
+    branchPushRule.run(textCtx({ ".github/workflows/release.yml": "on:\n  push:\n    tags:\n      - 'v*'\n" })),
