+  workflow_dispatch:
+jobs:
+  j:
+    steps:
+      - run: |
+          on:
+          push:
+            branches:
+              - anything
+          git push origin HEAD
+`,
+  }));
+  assert.deepEqual(out, [], `expected no findings, got ${JSON.stringify(out, null, 2)}`);
+});
+
